/* Boarding selection and journey summary share the active arrival corridor. */
function departureChoice(m){return m.vehicles.map(v=>({v,t:atBoard(v,m)})).filter(x=>x.t&&x.t.expectedDeparture>=m.now).sort((a,b)=>a.t.expectedArrival-b.t.expectedArrival)[0]}
function rememberBoarding(){try{localStorage.setItem('metroBoardingChoice',JSON.stringify({route:arrivalRoute,direction:arrivalDirection,stop:arrivalBoard}))}catch{}}
function chooseBoardingStop(id){let m=arrivalModel();if(!m.ids.includes(id))return;arrivalBoard=id;arrivalBus='';rememberBoarding();closeModal();render();toast('Boarding at '+stopName(id))}
function boardingOptions(query=''){let m=arrivalModel(),q=query.trim().toLocaleLowerCase(),items=m.ids.filter(id=>{let s=ns(id);return Object.values(s.name).join(' ').toLocaleLowerCase().includes(q)});return items.length?items.map(id=>{let selected=id===arrivalBoard,t=m.vehicles.map(v=>v.times.find(t=>t.stopId===id)).filter(t=>t&&t.expectedDeparture>=m.now).sort((a,b)=>a.expectedArrival-b.expectedArrival)[0];return `<button type="button" class="boarding-option ${selected?'is-selected':''}" aria-pressed="${selected}" onclick="chooseBoardingStop('${id}')"><span class="boarding-pin">${ic('pin')}</span><span><b>${safe(stopName(id))}</b><small>${safe(ns(id).name.si||'')}${ns(id).name.ta?' · '+safe(ns(id).name.ta):''}</small></span><span class="boarding-option-end">${selected?ic('check'):''}<small>${t?(t.expectedArrival<=m.now?'At stop':Math.ceil(t.expectedArrival-m.now)+' min'):'-'}</small></span></button>`}).join(''):'<div class="boarding-no-results"><b>No matching stops</b><p>Try another name on this route.</p></div>'}
function openBoardingSheet(){let m=arrivalModel();modal('Choose your boarding stop',`<div class="boarding-sheet-meta">${routeTag(arrivalRoute)}<span>Towards ${safe(stopName(m.ids.at(-1)))}</span><span class="tiny">Demo ETAs</span></div><label class="boarding-search" for="boarding-search">${ic('search')}<input id="boarding-search" type="search" aria-label="Search a stop" placeholder="Search a stop" autocomplete="off" oninput="document.getElementById('boarding-options').innerHTML=boardingOptions(this.value)"></label><div class="boarding-list-caption"><span>STOPS ON THIS ROUTE</span><span>${m.ids.length} stops</span></div><div id="boarding-options" role="group" aria-label="Boarding stops">${boardingOptions()}</div>`);$('.sheet')?.classList.add('boarding-sheet')}
arrivalHero=function(){let m=arrivalModel(),first=departureChoice(m),t=first?.t,last=first?.v.times.find(t=>t.stopId===m.ids.at(-1)),duration=t&&last?Math.max(0,Math.round(last.expectedArrival-t.expectedDeparture)):null,parts=m.route.name.en.split(/\s*[↔→–]\s*/),from=parts.length===2?parts[arrivalDirection===1?0:1]:stopName(m.ids[0]),to=parts.length===2?parts[arrivalDirection===1?1:0]:stopName(m.ids.at(-1)),delay=t?Math.max(0,Math.round(t.expectedArrival-t.scheduledArrival)):0;return `<article class="journeycard arrival-hero arc-hero" style="--journey-color:${m.route.color}"><div class="journeybody"><div class="between">${routeTag(arrivalRoute)}${modeBadge()}</div><div class="journey-dome" role="img" aria-label="${safe(from)} to ${safe(to)}, ${duration===null?'ride time unavailable':duration+' minute estimated ride from '+stopName(arrivalBoard)}"><svg viewBox="0 0 320 116" aria-hidden="true"><path class="dome-track" d="M20 104C35 -10 285 -10 300 104"/><path class="dome-arrow" d="m115 12 14 4-10 11M224 28l13 8-13 7"/><circle cx="20" cy="104" r="4"/><circle cx="300" cy="104" r="4"/></svg><div class="dome-time"><b>${duration===null?'-':duration}<small>${duration===null?'':' min'}</small></b><span>Estimated ride</span></div></div><div class="dome-endpoints"><b>${safe(from)}</b><button onclick="switchArrivalDirection();rememberBoarding()" aria-label="Reverse journey direction">⇄</button><b>${safe(to)}</b></div><button class="boarding-picker" onclick="openBoardingSheet()" aria-haspopup="dialog"><span class="boarding-pin">${ic('pin')}</span><span><small>BOARDING AT</small><b>${safe(stopName(arrivalBoard))}</b></span><span class="boarding-picker-change">Change ${ic('chevron')}</span></button><div class="arc-arrival-summary"><div><small>NEXT AT YOUR STOP</small><strong>${first?waitLabel(t,{...m,bus:first.v}):'ETA unavailable'}</strong><span>${t?'Arrives '+etaClock(t.expectedArrival):'No current prediction'}</span></div><div class="arc-status-chips">${t?`<span class="signal ${delay?'late':'ontime'}">${ic('clock')}${delay?'+'+delay+'m delay':'On time'}</span>${crowdChip(first.v)}`:''}</div></div><div class="arc-summary-facts"><span>Departs<b>${t?etaClock(t.expectedDeparture):'-'}</b></span><span>Arrive at destination<b>${last?etaClock(last.expectedArrival):'-'}</b></span><span>Frequency<b>40 min</b></span></div><p class="arc-estimate-note">Ride estimate from ${safe(stopName(arrivalBoard))} · demo conditions</p><div class="arrival-hero-actions"><button class="primary" onclick="arrivalFollow=!arrivalFollow;render()">${ic(arrivalFollow?'check':'bell')}${arrivalFollow?'Following':'Follow this route'}</button><button class="secondary" onclick="openArrivalContext()">${ic('clock')}Journey context</button></div></div><div class="journeyfooter"><button onclick="openArrivalRoutePicker()">${ic('bus')}Change route</button><button onclick="openNetworkMap()">${ic('pin')}See on map</button></div></article>`};
try{let saved=JSON.parse(localStorage.getItem('metroBoardingChoice'));if(saved&&network.routes[saved.route]&&network.routes[saved.route].orderedStops.includes(saved.stop)){arrivalRoute=saved.route;arrivalDirection=saved.direction===-1?-1:1;arrivalBoard=saved.stop}}catch{}
render();
